/*
 * sound_classify.h - the two-stage on-device sound classifier.   Owner: Rhaylene. Pure C.
 *
 *   stage 1: group (AMBIENT, BIRD, MAMMAL, INSECT_FROG, HUMAN, VEHICLE, WEATHER), confidence c1
 *   stage 2: for an animal group, the animal (e.g. DOG), confidence c2
 *   combined confidence c = (c1 * c2 + 50) / 100, about P(group) * P(animal | group)
 *   rejection: the animal label is kept if c >= SOUND_STAGE2_MIN_CONF, else the group with c1
 *
 * The trees are generated by ml/export_c.py into sound_model.h (static const, flash only). Every
 * node compares one float feature with a float threshold; a leaf holds its class distribution as
 * uint8 percent; a forest sums its trees' percents. No malloc, no recursion, a few hundred bytes of
 * stack. ml/qmodel.py computes the same thing in Python; host/tests/test_sound_model.c checks the two
 * agree on 200 test captures.
 */
#ifndef SOUND_CLASSIFY_H
#define SOUND_CLASSIFY_H

#include <stdint.h>

#include "sound_features.h"

#define SM_MAX_CLASSES 16

typedef struct
{
    const int8_t* p_feat;  /* per internal node: feature index */
    const float* p_thr;    /* go left if f[feat] <= thr */
    const int16_t* p_left; /* >= 0: internal node; < 0: leaf -(child + 1) */
    const int16_t* p_right;
    const uint8_t* p_leaf; /* n_leaves x n_classes, percent */
    int16_t root;        /* 0, or a leaf code if the whole tree is one leaf */
} sm_tree_t;

typedef struct
{
    const sm_tree_t* p_trees;
    uint8_t n_trees;
    uint8_t n_classes;
    const uint8_t* p_classes; /* label id of each class */
} sm_model_t;

/* One stage: label id of the winning class and its confidence 0-100. */
void sm_predict(const sm_model_t* p_model, const float* p_features, uint8_t* p_label, uint8_t* p_conf);

/* Both stages + rejection. label_id: common/sound_classes.h. conf 0-100. */
void sound_classify(const float features[SF_N_FEATURES], uint8_t* p_label_id, uint8_t* p_conf);

/* The rejection threshold the model was exported with (SOUND_STAGE2_MIN_CONF). */
uint8_t sound_classify_min_conf(void);

#endif
